18: # Ratings by direction, so the page can show which way the call leans.
19: _TONE = {"Buy": "up", "Overweight": "up", "Hold": "level", "Underweight": "down", "Sell": "down"}
20: 
21: # The Tauric Research logo as published (tauric.ai/brand/tauric-logo.svg), drawn
22: # in the page so it loads nothing.
23: _LOGO = files("tradingagents").joinpath("assets/tauric-logo.svg").read_text(encoding="utf-8").strip()
24: _COMPANY = "https://tauric.ai"
25: _ORG = "https://github.com/TauricResearch"
