141: main h2 + h3 { margin-top: 1.25rem; padding-top: 0; border-top: 0; }
142: main h4, main h5, main h6 { margin: 1.75rem 0 0.5rem; font: 600 1rem/1.4 var(--sans); }
143: main h5, main h6 { color: var(--muted); }
144: main p, main ul, main ol { margin: 0 0 1rem; }
