162: @media (max-width: 34rem) {
163:   body { font-size: 16px; }
164:   .page { padding: 2rem 1rem 3rem; }
165:   .masthead h1 { font-size: 2rem; }
166:   .masthead .logo svg { height: 1.25rem; }
167:   .run { grid-template-columns: 1fr; gap: 0 0; }
168:   .run dd { margin-bottom: 0.45rem; }
169:   .run .group { white-space: normal; }
