171: @media print {
172:   :root { --paper: #fff; --ink: #000; --muted: #444; --rule: #bbb; --accent: #000; --wash: #f2f2f2;
173:     --edge: #bbb; --up: #087a59; --down: #b4372f; --level: #444; }
174:   body { font-size: 11pt; }
175:   .table { overflow: visible; }
176:   .page { max-width: none; padding: 0; }
177:   .contents, .to-top { display: none; }
178:   main h2 { break-before: page; border-top: 0; margin-top: 0; }
179:   main section:first-child h2 { break-before: auto; }
180:   main h3, main h4 { break-after: avoid; }
181:   a { color: inherit; text-decoration: none; }
182:   table { break-inside: avoid; }
183: }
184: """
185: 
186: 
187: def _markdown() -> MarkdownIt:
188:     md = MarkdownIt("commonmark", {"html": False}).enable("table").disable("image")
189:     md.add_render_rule("table_open", lambda *a: '<div class="table"><table>\n')
190:     md.add_render_rule("table_close", lambda *a: "</table></div>\n")
191:     return md
192: 
193: 
194: def _render_agent_text(md: MarkdownIt, text: str) -> str:
195:     """An agent's text, its own headings placed below the agent's heading (h3)."""
196:     tokens = md.parse(text)
197:     for token in tokens:
198:         if token.type in ("heading_open", "heading_close"):
199:             token.tag = f"h{min(int(token.tag[1]) + 3, 6)}"
200:     return md.renderer.render(tokens, md.options, {})
201: 
202: 
203: # What each data category serves, as a reader would name it.
204: _CATEGORY = {
205:     "core_stock_apis": "Prices", "technical_indicators": "Indicators", "fundamental_data": "Fundamentals",
206:     "news_data": "News", "macro_data": "Macro", "prediction_markets": "Prediction markets",
207: }
208: 
209: 
210: def _fields(values) -> str:
211:     return " ".join(f'<span class="field">{escape(str(v))}</span>' for v in values)
212: 
213: 
214: def _chain(vendors: str) -> str:
215:     """A vendor chain in the order it is tried: ``a,b`` reads a, then b."""
216:     names = [v.strip() for v in str(vendors).split(",") if v.strip()]
217:     return ' <span class="then">\u2192</span> '.join(_fields([n]) for n in names)
218: 
219: 
220: def _group(name: str, values_html: str) -> str:
221:     return f'<span class="group"><span class="name">{escape(name)}</span>{values_html}</span>'
222: 
223: 
224: def _run_details(final_state: dict, settings: dict | None) -> list[tuple[str, str]]:
225:     """The run details as (label, value HTML); every value from the run is escaped."""
226:     details = [("Generated", escape(datetime.now().strftime("%Y-%m-%d %H:%M")))]
227:     if settings:
228:         s = settings.get
229:         for tier in ("deep", "quick"):
230:             provider = s(f"{tier}_think_provider") or s("llm_provider", "?")
231:             details.append((f"{tier.capitalize()} model", _fields([provider, s(f"{tier}_think_llm", "?")])))
232:         details.append(("Analysts", _fields(analyst_names(s("analysts")))))
233:         details.append(("Debate rounds", " ".join((
234:             _group("research", _fields([s("max_debate_rounds", "?")])),
235:             _group("risk", _fields([s("max_risk_discuss_rounds", "?")])),
236:         ))))
237:         vendors = {**(s("data_vendors") or {}), **(s("tool_vendors") or {})}
238:         if vendors:
239:             details.append(("Data vendors", " ".join(
240:                 _group(_CATEGORY.get(k, k), _chain(v)) for k, v in vendors.items()
241:             )))
242:         details.append(("Version", escape(f"TradingAgents {s('version', '?')}")))
243:     if final_state.get("memory_note"):
244:         details.append(("Memory log", escape(final_state["memory_note"])))
245:     return details
246: 
247: 
248: def render_report(ticker: str, final_state: dict, settings: dict | None, parts) -> str:
249:     """The report page: title and rating, what produced the run, contents, sections."""
250:     md = _markdown()
251:     blocked = final_state.get("publication_status") == "BLOCKED"
252:     if blocked:
253:         # FR-01: a blocked run has no official rating; show the status instead.
254:         rating = f"BLOCKED ({final_state.get('publication_reason') or 'BLOCKED'})"
255:         tone = "review"
256:     else:
257:         rating = run_rating(final_state) if final_state.get("final_trade_decision") else ""
258:         tone = _TONE.get(rating, "review")
259:     date = final_state.get("trade_date", "")
260: 
261:     title = f'<span class="ticker">{escape(ticker)}</span>'
262:     if rating:
263:         title += f' <span class="rating {tone}">{escape(rating)}</span>'
264:     details = "".join(
265:         f'<div class="{"note" if label == "Memory log" else "detail"}">'
266:         f"<dt>{escape(label)}</dt><dd>{value}</dd></div>"
267:         for label, value in _run_details(final_state, settings)
268:     )
269: 
270:     contents, body = [], []
271:     for n, (heading, _folder, written) in enumerate(parts, 1):
272:         agents = "".join(
273:             f'<li><a href="#s{n}-{m}"><span class="bar"></span> <span class="label">{escape(agent)}</span></a></li>'
274:             for m, (agent, _f, _t) in enumerate(written, 1)
275:         )
276:         numeral, _, name = heading.partition(". ")
277:         contents.append(f'<li><a href="#s{n}"><span class="num">{escape(numeral)}</span> '
278:                         f'<span class="label">{escape(name)}</span></a><ul>{agents}</ul></li>')
279:         body.append(f'<section id="s{n}"><h2>{escape(heading)}</h2>')
280:         for m, (agent, _filename, text) in enumerate(written, 1):
281:             body.append(f'<h3 id="s{n}-{m}">{escape(agent)}</h3>\n{_render_agent_text(md, text)}')
282:         body.append("</section>")
283: 
284:     page_title = " ".join(x for x in (ticker, date, rating) if x)
285:     return f"""<!doctype html>
286: <html lang="en">
287: <head>
288: <meta charset="utf-8">
289: <meta name="viewport" content="width=device-width, initial-scale=1">
290: <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'">
291: <title>{escape(page_title)}: TradingAgents report</title>
292: <style>{_CSS}</style>
293: </head>
294: <body>
295: <div class="page" id="top">
296: <header class="masthead">
297: <a class="logo" href="{_COMPANY}" rel="noopener" aria-label="Tauric Research">{_LOGO}</a>
298: <h1>{title}</h1>
299: <p class="date">{escape(f"Analysis of {date}" if date else "Analysis")}</p>
300: <dl class="run">{details}</dl>
301: </header>
302: <nav class="contents" aria-label="Sections"><ul>{"".join(contents)}</ul></nav>
303: <main>
304: {"".join(body)}
305: </main>
306: <footer class="credit"><a href="{_PROJECT}" rel="noopener">TradingAgents</a> powered by <a class="brand" href="{_ORG}" rel="noopener">Tauric Research</a></footer>
307: </div>
308: <a class="to-top" href="#top">Top</a>
309: </body>
310: </html>
311: """
